tools.script:
extends RefCounted
func execute(tree:SceneTree)->Variant:
 tree.root.disable_3d=true
 var runner=load("res://tests/_mcp_body_native.gd").new()
 var result:Dictionary=await runner.run(tree)
 return result

extends RefCounted
func execute(tree:SceneTree)->Variant:
 tree.root.disable_3d=true
 return await load("res://tests/_mcp_body_unit.gd").new().run(tree)

extends RefCounted
func execute(tree:SceneTree)->Variant:
 tree.root.disable_3d=true
 var runner=load("res://tests/first_person_body_view_test.gd").new()
 tree.root.add_child(runner)
 await runner._run()
 var result={"checks":runner.checks,"failures":runner.failures,"finished":runner.finished,"rendered_captures":false}
 runner.queue_free()
 await tree.process_frame
 return result
